package com.smartspend.dao;
import com.smartspend.model.Notification;import com.smartspend.util.DatabaseConnection;import java.sql.*;import java.util.*;
public class NotificationDAO {public List<Notification> findAll(int uid){List<Notification>a=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC")){p.setInt(1,uid);try(ResultSet r=p.executeQuery()){while(r.next())a.add(new Notification(r.getInt("id"),uid,r.getString("title"),r.getString("message"),r.getString("type"),r.getBoolean("is_read"),r.getTimestamp("created_at").toLocalDateTime()));}}catch(SQLException e){throw new RuntimeException(e);}return a;}
 public int unreadCount(int uid){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0")){p.setInt(1,uid);try(ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}catch(SQLException e){throw new RuntimeException(e);}}
 public void add(int uid,String title,String msg,String type){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO notifications(user_id,title,message,type,is_read) VALUES(?,?,?,?,0)")){p.setInt(1,uid);p.setString(2,title);p.setString(3,msg);p.setString(4,type);p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}
 public void markRead(int id,int uid){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?")){p.setInt(1,id);p.setInt(2,uid);p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}
 public void markAllRead(int uid){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE notifications SET is_read=1 WHERE user_id=?")){p.setInt(1,uid);p.executeUpdate();}catch(SQLException e){throw new RuntimeException(e);}}
}
